-- Populate codes for Cameroon administrative hierarchy (regions, departments, subdivisions)
-- Unblocks EstablishmentIdGenerator during company registration approval.
-- Region codes: 01 to 10 (2 digits)
-- Department codes: 01 to 58 (2 digits)
-- Subdivision codes: 0101 to 5806 (4 digits: department code + 2-digit subdivision index)

-- 1. Regions
UPDATE "regions" SET "code" = '01' WHERE "name" = 'Adamaoua' AND "code" IS NULL;
UPDATE "regions" SET "code" = '02' WHERE "name" = 'Centre' AND "code" IS NULL;
UPDATE "regions" SET "code" = '03' WHERE "name" = 'Est' AND "code" IS NULL;
UPDATE "regions" SET "code" = '04' WHERE "name" = 'Extrême-Nord' AND "code" IS NULL;
UPDATE "regions" SET "code" = '05' WHERE "name" = 'Littoral' AND "code" IS NULL;
UPDATE "regions" SET "code" = '06' WHERE "name" = 'Nord' AND "code" IS NULL;
UPDATE "regions" SET "code" = '07' WHERE "name" = 'Nord-Ouest' AND "code" IS NULL;
UPDATE "regions" SET "code" = '08' WHERE "name" = 'Ouest' AND "code" IS NULL;
UPDATE "regions" SET "code" = '09' WHERE "name" = 'Sud' AND "code" IS NULL;
UPDATE "regions" SET "code" = '10' WHERE "name" = 'Sud-Ouest' AND "code" IS NULL;

